#!/usr/bin/env bash
# Exercise recipe arithmetic, generated bytes, requested formats and cache repair.
set -euo pipefail
export LC_ALL=C MAKE_JOBS=1 MAKE_FORMAT=plain ALLOW_BIG_TIERS=0
here="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
runner="$here/../lib/shapes/make.sh" catalog="$here/../lib/shapes/synthetic.json"
work="$(mktemp -d /var/tmp/fastq-shapes-check.XXXXXX)"
files=() dirs=() pid=''
declare -A registered=()
die() {
    printf 'fail: %s\n' "$*" >&2
    exit 1
}
cleanup() {
    local rc=$? i
    trap - EXIT
    if [[ -n "$pid" ]]; then
        kill -TERM "$pid" 2>/dev/null || true
        wait "$pid" 2>/dev/null || true
    fi
    if ((${#files[@]})); then rm -f -- "${files[@]}" || rc=1; fi
    for ((i = ${#dirs[@]} - 1; i >= 0; i--)); do rmdir -- "${dirs[i]}" || rc=1; done
    rmdir -- "$work" || rc=1
    exit "$rc"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM
build() {
    local root="$1" plan shape file dir
    shift
    plan="$(bash "$runner" --plan --root "$root" "$@")"
    shape="$(jq -r .shape <<<"$plan")"
    for dir in "$root" "$root/$shape"; do
        if [[ ! -v "registered[$dir]" ]]; then
            mkdir -p -- "$dir"
            dirs+=("$dir")
            registered[$dir]=1
        fi
    done
    while IFS= read -r file; do files+=("$root/$shape/$file"); done < <(jq -r '.files[],"state.json"' <<<"$plan")
    bash "$runner" --root "$root" "$@" >/dev/null
}
validate() {
    local file="$1" count="$2"
    [[ "$(wc -l <"$file")" == $((count * 4)) ]] || die "wrong record count: $file"
    tail -c 1 -- "$file" | cmp -s - <(printf '\n') || die "missing final newline: $file"
    awk '
        { sub(/\r$/, "") }
        NR%4==1 { if ($0 !~ /^@[^[:space:]]/) exit 1 }
        NR%4==2 { n=length($0); if ($0 !~ /^[ACGTURYSWKMBDHVNacgturyswkmbdhvn]+$/) exit 1 }
        NR%4==3 { if ($0 !~ /^\+/) exit 1 }
        NR%4==0 { if (length($0)!=n || $0 !~ /^[!-~]+$/) exit 1 }
    ' "$file" || die "invalid FASTQ: $file"
}
mapfile -t shapes < <(bash "$runner" --list | jq -r '.shapes[].id')
bash "$runner" --plan --root "$work/absent" dense tiny >/dev/null
[[ ! -e "$work/absent" ]] || die 'planning created output directories'
for shape in "${shapes[@]}"; do
    tier=tiny
    [[ "$shape" != long ]] || tier=xsmall
    plan="$(bash "$runner" --plan "$shape" "$tier")"
    count="$(jq -r .count <<<"$plan")"
    build "$work/serial" --paired-layout both "$shape" "$tier"
    build "$work/parallel" --jobs 4 --formats all --paired-layout both "$shape" "$tier"
    suffixes=(.fastq)
    [[ "$shape" != paired ]] || suffixes=(_R1.fastq _R2.fastq _interleaved.fastq)
    for suffix in "${suffixes[@]}"; do
        file="$work/parallel/$shape/$tier$suffix"
        expected="$count"
        [[ "$suffix" != _interleaved.fastq ]] || expected=$((count * 2))
        validate "$file" "$expected"
        cmp -- "$work/serial/$shape/$tier$suffix" "$file"
        gzip -t -- "$file.gz"
        gzip -cd -- "$file.gz" | cmp -- "$file" -
    done
    if [[ "$shape" == paired ]]; then
        paste -d '\n' <(paste - - - - <"$work/parallel/paired/${tier}_R1.fastq") \
            <(paste - - - - <"$work/parallel/paired/${tier}_R2.fastq") | tr '\t' '\n' | cmp -- "$work/parallel/paired/${tier}_interleaved.fastq" -
    elif [[ "$shape" == dense ]]; then
        gzip -t -- "$work/parallel/dense/$tier.multi.fastq.gz"
        gzip -cd -- "$work/parallel/dense/$tier.multi.fastq.gz" | cmp -- "$work/parallel/dense/$tier.fastq" -
    fi
    before="$(stat -c '%i:%s:%y:%z' -- "$work/parallel/$shape/state.json")"
    build "$work/parallel" --jobs 4 --formats all --paired-layout both "$shape" "$tier"
    [[ "$before" == "$(stat -c '%i:%s:%y:%z' -- "$work/parallel/$shape/state.json")" ]] || die 'cache hit rewrote state'
    for start in 65 9999998 999999995; do
        build "$work/chunks" --count 5 --start "$start" --paired-layout both "$shape" whole
        build "$work/chunks" --count 3 --start "$start" --paired-layout both "$shape" first
        build "$work/chunks" --count 2 --start "$((start + 3))" --paired-layout both "$shape" last
        for suffix in "${suffixes[@]}"; do
            cat -- "$work/chunks/$shape/first$suffix" "$work/chunks/$shape/last$suffix" | cmp -- "$work/chunks/$shape/whole$suffix" -
        done
    done
    if bash "$runner" --count 2 --start 999999999 "$shape" whole "$work/chunks" >/dev/null 2>&1; then die 'accepted overflowing record range'; fi
    for tier in tiny xsmall small medium large; do
        bash "$runner" --plan "$shape" "$tier" | jq -e '.count > 0 and .decompressed_bytes <= .byte_cap' >/dev/null
    done
    printf 'pass: %s structure, chunk bytes, compression, cache and tier plans\n' "$shape"
done
# Pools: every record is a real read (or its prefix) with its own qualities,
# mates come from one real pair, sizes match the unit recipe, seeds replicate.
pool="$here/../data/real"
real_records() { awk -v n="$2" 'NR % 4 == 2 { s = substr($0, 1, n) } NR % 4 == 0 { print s "\t" substr($0, 1, n) }' "$1"; }
build "$work/pool" --formats all dense tiny
awk -F'\t' 'NR == FNR { real[$0]; next } FNR % 4 == 2 { s = $0 } FNR % 4 == 0 && !((s "\t" $0) in real) { exit 1 }' \
    <(real_records "$pool/illumina-drr1001190/xsmall_R1.fastq" 150) "$work/pool/dense/tiny.fastq" || die 'dense record is not a real read'
build "$work/pool" --paired-layout both paired tiny
paste <(real_records "$pool/illumina-drr018447/xsmall_R1.fastq" 100) <(real_records "$pool/illumina-drr018447/xsmall_R2.fastq" 100) >"$work/pairs.tsv"
files+=("$work/pairs.tsv" "$work/unit.json" "$work/log")
paste <(awk 'NR % 4 == 2 || NR % 4 == 0' "$work/pool/paired/tiny_R1.fastq" | paste - -) \
    <(awk 'NR % 4 == 2 || NR % 4 == 0' "$work/pool/paired/tiny_R2.fastq" | paste - -) |
    awk -F'\t' 'NR == FNR { real[$0]; next } !($0 in real) { exit 1 }' "$work/pairs.tsv" - || die 'paired mates are not a real pair'
jq '.shapes[0] |= (del(.pool) | .sequence_unit = "ACGT" | .quality_unit = "I")' "$catalog" >"$work/unit.json"
build "$work/unit" --catalog "$work/unit.json" dense tiny
[[ "$(stat -c%s "$work/unit/dense/tiny.fastq")" == "$(stat -c%s "$work/pool/dense/tiny.fastq")" ]] || die 'pool changed the file size'
ratio=$(($(stat -c%s "$work/pool/dense/tiny.fastq") / $(stat -c%s "$work/pool/dense/tiny.fastq.gz")))
((ratio < 10)) || die "pool output compresses ${ratio}x"
build "$work/pool" --seed 7 dense tiny
[[ "$(stat -c%s "$work/pool/dense/tiny-s7.fastq")" == "$(stat -c%s "$work/pool/dense/tiny.fastq")" ]] || die 'seed changed the file size'
if cmp -s "$work/pool/dense/tiny.fastq" "$work/pool/dense/tiny-s7.fastq"; then die 'seed did not change content'; fi
if bash "$runner" --seed 1 --catalog "$work/unit.json" --plan dense tiny >/dev/null 2>&1; then die 'accepted a seed without a pool'; fi
jq '.shapes[0].pool = "absent-source/xsmall_R1.fastq"' "$catalog" >"$work/catalog.json"
if bash "$runner" --catalog "$work/catalog.json" --root "$work/absent" dense tiny 2>"$work/log" >/dev/null; then die 'built without its pool'; fi
grep -q 'missing pool' "$work/log" || die 'missing pool message'
printf 'pass: pool reads, real mates, unchanged sizes, gzip ratio %sx, seeds, missing pool\n' "$ratio"
# A JSON-only recipe exercises short quality units, custom length and CRLF.
files+=("$work/catalog.json" "$work/expected.fastq")
jq '.shapes += [.shapes[0] | del(.pool) | .id="mini" | .lengths=[3] | .sequence_unit="ACGT" | .quality_unit="!" | .line_endings="alternating_crlf_lf" | .multi_gzip_members=2]' "$catalog" >"$work/catalog.json"
build "$work/variants" --catalog "$work/catalog.json" --count 3 mini sample
printf '@D000000001\r\nACG\r\n+\r\n!!!\r\n@D000000002\nACG\n+\n!!!\n@D000000003\r\nACG\r\n+\r\n!!!\r\n' >"$work/expected.fastq"
cmp -- "$work/expected.fastq" "$work/variants/mini/sample.fastq"
build "$work/variants" --catalog "$work/catalog.json" --count 3 --formats multi_gzip mini sample
[[ ! -e "$work/variants/mini/sample.fastq.gz" ]] || die 'created an unrequested format'
compressor=(gzip -n -6 -c)
if command -v pigz >/dev/null; then compressor=(pigz -p 2 -n -6 -c); fi
{
    head -n 8 "$work/expected.fastq" | "${compressor[@]}"
    tail -n 4 "$work/expected.fastq" | "${compressor[@]}"
} | cmp -- "$work/variants/mini/sample.multi.fastq.gz" -
jq '.shapes[0] |= (del(.pool) | .sequence_unit="ACGT" | .quality_unit="\\\"")' "$catalog" >"$work/catalog.json"
build "$work/variants" --catalog "$work/catalog.json" --count 1 --length 3 dense quoted
printf '@D000000001\nACG\n+\n\134\042\134\n' >"$work/expected.fastq"
cmp -- "$work/expected.fastq" "$work/variants/dense/quoted.fastq"
before="$(stat -c '%i:%s:%y:%z' -- "$work/variants/dense/state.json")"
build "$work/variants" --catalog "$work/catalog.json" --count 1 --length 3 dense quoted
[[ "$before" == "$(stat -c '%i:%s:%y:%z' -- "$work/variants/dense/state.json")" ]] || die 'escaped quality bytes broke caching'
build "$work/gzip-only" --count 3 --formats gzip --length 3 dense sample
[[ ! -e "$work/gzip-only/dense/sample.fastq" ]] || die 'gzip-only published plain data'
build "$work/gzip-only" --count 1000 --formats gzip dense threads
build "$work/gzip-only" --count 1000 --formats gzip --jobs 4 dense threads_parallel
cmp -- "$work/gzip-only/dense/threads.fastq.gz" "$work/gzip-only/dense/threads_parallel.fastq.gz"
before="$(stat -c '%i:%s:%y:%z' -- "$work/gzip-only/dense/threads.fastq.gz")"
build "$work/gzip-only" --count 1000 --formats gzip --jobs 4 dense threads
[[ "$before" == "$(stat -c '%i:%s:%y:%z' -- "$work/gzip-only/dense/threads.fastq.gz")" ]] || die 'worker count invalidated cached gzip'
MAKE_FORMAT='' build "$work/mates" --count 3 paired sample
[[ -f "$work/mates/paired/sample_R1.fastq.gz" && -f "$work/mates/paired/sample_R2.fastq.gz" ]] || die 'default paired build omitted gzip files'
[[ ! -e "$work/mates/paired/sample_interleaved.fastq" ]] || die 'default paired build published interleaving'
# Repairs must preserve valid inputs; unrelated catalogue edits are cache hits.
out="$work/parallel/dense/tiny.fastq"
before="$(stat -c '%i:%s:%y:%z' -- "$out")"
rm -- "$out.gz"
build "$work/parallel" --jobs 4 --formats all dense tiny
[[ "$before" == "$(stat -c '%i:%s:%y:%z' -- "$out")" ]] || die 'gzip repair regenerated plain data'
jq '.revision+=1 | .shapes[0].description="changed description" | .shapes[1].lengths=[5]' "$catalog" >"$work/catalog.json"
build "$work/parallel" --catalog "$work/catalog.json" dense tiny
[[ "$before" == "$(stat -c '%i:%s:%y:%z' -- "$out")" ]] || die 'unrelated catalogue edit regenerated data'
printf '@damaged\nA\n+\nI\n' >"$out"
build "$work/parallel" dense tiny
cmp -- "$work/serial/dense/tiny.fastq" "$out"
build "$work/parallel" --formats gzip dense tiny
before="$(cksum -- "$out" "$out.gz" "$work/parallel/dense/state.json")"
mkdir "$work/bin"
dirs+=("$work/bin")
for tool in pigz gzip; do
    files+=("$work/bin/$tool")
    cat >"$work/bin/$tool" <<'MOCK'
#!/usr/bin/env bash
if [[ "$1" == --version ]]; then echo failed-compressor; exit 0; fi
if [[ -n "${SHAPES_CHECK_READY:-}" ]]; then
    printf '%s\n' "$$" >"$SHAPES_CHECK_READY"
    exec sleep 30
fi
exit 42
MOCK
    chmod +x "$work/bin/$tool"
done
if PATH="$work/bin:$PATH" bash "$runner" --formats gzip dense tiny "$work/parallel" >/dev/null 2>&1; then die 'ignored compressor failure'; fi
[[ "$before" == "$(cksum -- "$out" "$out.gz" "$work/parallel/dense/state.json")" ]] || die 'failed compression changed completed files'
files+=("$work/ready")
PATH="$work/bin:$PATH" SHAPES_CHECK_READY="$work/ready" bash "$runner" --formats gzip dense tiny "$work/parallel" >/dev/null 2>&1 &
pid=$!
for ((n = 0; n < 100; n++)); do
    [[ ! -s "$work/ready" ]] || break
    sleep 0.02
done
[[ -s "$work/ready" ]] || die 'compressor did not start'
worker="$(cat "$work/ready")"
scratch="$(dirname -- "$(readlink "/proc/$worker/fd/1")")"
if flock -n "$work/parallel/dense" true; then die 'shape directory was not locked'; fi
kill -TERM "$pid"
if wait "$pid"; then die 'termination reported success'; else status=$?; fi
pid=''
[[ "$status" == 143 && ! -d "$scratch" ]] || die 'termination did not clean scratch'
if kill -0 "$worker" 2>/dev/null; then die 'termination left a worker running'; fi
[[ "$before" == "$(cksum -- "$out" "$out.gz" "$work/parallel/dense/state.json")" ]] || die 'termination changed completed files'
flock -n "$work/parallel/dense" true || die 'termination left the shape locked'
jq '.shapes[0] |= (del(.pool) | .sequence_unit="T" | .quality_unit="I")' "$catalog" >"$work/catalog.json"
build "$work/parallel" --catalog "$work/catalog.json" dense tiny
[[ "$(head -n 2 "$out" | tail -n 1)" =~ ^T+$ ]] || die 'recipe edit reused stale data'
for change in '.shapes[0].lenghts=[3]' '.shapes[0] |= (del(.pool) | .sequence_unit="A\nT" | .quality_unit="I")' '.shapes[0] |= (del(.pool) | .sequence_unit="A" | .quality_unit="I\n")' '.shapes[0].sequence_unit="A"' '.shapes[0] |= del(.pool)' '.shapes[0].pool="../x.fastq"' '.shapes[3].pool="illumina-drr018447/xsmall_R2.fastq"' '.shapes[0].header.prefix="%s"' '.shapes[0].engine="other"' '.shapes[1].id="dense"' '.tiers.xlarge=100'; do
    jq "$change" "$catalog" >"$work/catalog.json"
    if bash "$runner" --catalog "$work/catalog.json" --plan dense tiny >/dev/null 2>&1; then die "accepted invalid catalogue: $change"; fi
done
if bash "$runner" --plan dense xlarge >/dev/null 2>&1; then die 'accepted removed tier'; fi
printf 'pass: JSON variants, requested files, member boundaries, cache repair and failed writes\n'
